def filename(kind, lang):
    return f"{kind}.html" if lang == "en" else f"{kind}-{lang}.html"

def linked(text):
    return html.escape(text).replace("dhalska2@gmail.com", '<a href="mailto:dhalska2@gmail.com">dhalska2@gmail.com</a>')

FEATURES={"en":["Go · Janggi · Checkers · Chess · Gomoku","Live and correspondence matches","One profile, premium plan, and game inbox","10 launch languages"],"ko":["바둑 · 장기 · 체커 · 체스 · 오목","실시간 및 비동기 대국","하나의 프로필·프리미엄·대국함","출시 언어 10개"],"ja":["囲碁・チャンギ・チェッカー・チェス・五目並べ","リアルタイム・通信対局","ひとつのプロフィール、プラン、対局一覧","10言語対応"],"zh-hans":["围棋·韩国象棋·跳棋·国际象棋·五子棋","实时与异步对局","统一资料、高级方案和对局箱","支持10种语言"],"zh-hant":["圍棋·韓國象棋·跳棋·國際象棋·五子棋","即時與非同步對局","統一個人檔案、進階方案與對局匣","支援10種語言"],"de":["Go · Janggi · Dame · Schach · Gomoku","Live- und Fernpartien","Ein Profil, Premiumplan und Spieleingang","10 Startsprachen"],"fr":["Go · Janggi · Dames · Échecs · Gomoku","Parties en direct et différées","Un profil, une offre premium et une boîte de parties","10 langues au lancement"],"es":["Go · Janggi · Damas · Ajedrez · Gomoku","Partidas en directo y por turnos","Un perfil, plan premium y bandeja de partidas","10 idiomas de lanzamiento"],"pt-br":["Go · Janggi · Damas · Xadrez · Gomoku","Partidas ao vivo e assíncronas","Um perfil, plano premium e caixa de partidas","10 idiomas no lançamento"],"id":["Go · Janggi · Checkers · Chess · Gomoku","Laga langsung dan korespondensi","Satu profil, paket premium, dan kotak laga","10 bahasa saat peluncuran"]}

for lang, ui in LANGS.items():
    for kind in KINDS:
        title = ui["nav"][KINDS.index(kind)]
        nav = "".join(f'<a href="{filename(k,lang)}"{" aria-current=\"page\"" if k==kind else ""}>{html.escape(ui["nav"][i])}</a>' for i,k in enumerate(KINDS))
        options = "".join(f'<option value="{filename(kind,c)}"{" selected" if c==lang else ""}>{html.escape(v["label"])}</option>' for c,v in LANGS.items())
        alternates = "\n".join(f'<link rel="alternate" hreflang="{c}" href="{ROOT}{filename(kind,c)}">' for c in LANGS)
        if kind == "index":
            body=f'<p class="eyebrow">PANDAM</p><h1>{html.escape(ui["tag"])}</h1><p class="lead">{html.escape(ui["intro"])}</p><ul class="features">'+"".join(f'<li>{html.escape(v)}</li>' for v in FEATURES[lang])+'</ul><div class="cards">'+"".join(f'<a class="card" href="{filename(k,lang)}"><strong>{html.escape(ui["nav"][i])}</strong><span>↗</span></a>' for i,k in enumerate(KINDS) if k!="index")+"</div>"
        else:
            body=f'<h1>{html.escape(title)}</h1><p class="date">{html.escape(ui["date"])}</p>'+"".join(f'<section><h2>{i+1}. {html.escape(h)}</h2><p>{linked(p)}</p></section>' for i,(h,p) in enumerate(TEXT[lang][kind]))
        if kind == "privacy":
            body += '<aside><p><a href="https://supabase.com/privacy">Supabase Privacy</a> · <a href="https://www.apple.com/legal/privacy/">Apple Privacy</a> · <a href="https://policies.google.com/privacy">Google Privacy</a> · <a href="https://firebase.google.com/support/privacy">Firebase Privacy</a></p></aside>'
        if kind == "terms":
            body += '<p><a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">Apple Standard EULA</a></p>'
        subject = "Pandam%20Data%20Deletion" if kind == "delete-account" else "Pandam%20Support"
        body += f'<aside><h2>{html.escape(ui["contact"])}</h2><p>Next Studio · 넥스트 스튜디오<br><a href="mailto:dhalska2@gmail.com?subject={subject}">dhalska2@gmail.com</a></p></aside>'
        page=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Pandam · {html.escape(title)} · Next Studio"><title>Pandam · {html.escape(title)}</title><link rel="stylesheet" href="style.css"><link rel="icon" href="icon.png"><link rel="canonical" href="{ROOT}{filename(kind,lang)}">{alternates}<link rel="alternate" hreflang="x-default" href="{ROOT}{filename(kind,'en')}"></head><body><a class="skip" href="#content">{html.escape(ui["skip"])}</a><main><div class="top"><a class="brand" href="{filename('index',lang)}"><img src="icon.png" width="40" height="40" alt=""> PANDAM</a><label><span class="sr-only">Language</span><select class="language" aria-label="Language" onchange="location.href=this.value">{options}</select></label></div><nav aria-label="{html.escape(title)}">{nav}</nav><article id="content">{body}</article><footer>© 2026 Next Studio · 넥스트 스튜디오<br><a href="mailto:dhalska2@gmail.com">dhalska2@gmail.com</a></footer></main></body></html>'''
        (BASE/filename(kind,lang)).write_text(page,encoding="utf-8")
print(f"Generated {len(LANGS)*len(KINDS)} pages")
